<script setup>
import { computed, ref, shallowRef, watch } from 'vue'
import { useDashboardData } from '../composables/useDashboardData.js'
import { analyzeDividendQuality } from '../utils/dividendQuality.js'
import { membershipSignature } from '../utils/constituentStructure.js'
import { riskPercent } from '../utils/priceRisk.js'
import { downloadBlob } from '../utils/chartExport.js'

defineProps({ instrument: { type: String, default: 'H30269' } })
const dashboard = useDashboardData(), source = dashboard.states.fundamentals, current = dashboard.states.constituents
const loading = computed(() => source.loading || current.loading)
const error = computed(() => [source.error, current.error].filter(Boolean).join('；'))
const inputs = shallowRef(null), year = ref(null), query = ref(''), industry = ref('all'), filter = ref('all'), sort = ref('dividend'), selectedCode = ref(''), message = ref(''), detail = ref(null)
watch(() => [source.data, current.data, loading.value, error.value], () => {
  if (loading.value || error.value && inputs.value) return
  if (source.data) inputs.value = { data: source.data, current: current.data }
}, { immediate: true })
const data = computed(() => inputs.value?.data)
watch(data, value => { if (!value) return; if (!value.years.includes(year.value)) year.value = value.years.at(-1); if (!value.members.some(member => member.code === selectedCode.value)) selectedCode.value = '' }, { immediate: true })
const result = computed(() => { if (!data.value) return { stats: null, error: '' }; try { return { stats: analyzeDividendQuality(data.value, year.value), error: '' } } catch (error) { return { stats: null, error: error.message } } })
const stats = computed(() => result.value.stats)
const mismatch = computed(() => data.value && inputs.value.current && (data.value.membershipDate !== inputs.value.current.date || membershipSignature({ members: data.value.members }) !== membershipSignature(inputs.value.current)))
const unknownIndustries = computed(() => data.value?.members.filter(member => member.industry === null).length ?? 0)
const retainedIndustries = computed(() => data.value?.members.filter(member => member.industryStatus === 'stale').length ?? 0)
const hasWarning = computed(() => Boolean(error.value || result.value.error || !data.value || data.value.status !== 'ok' || data.value.membershipStatus !== 'ok' || !inputs.value?.current || inputs.value.current.status !== 'ok' || mismatch.value || unknownIndustries.value || retainedIndustries.value || stats.value?.rows.some(missingRow)))
const labels = { increase: '增加', decrease: '减少', flat: '持平', resumed: '由零转正', zero: '连续零分红', pending: '实施进度待完成', unknown: '缺少可比年度' }
const amount = number => Number.isFinite(number) ? `${(number / 1e8).toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} 亿` : '—'
const times = number => Number.isFinite(number) ? `${number.toFixed(2)} 倍` : '—'
const pct = number => riskPercent(number, false)
const time = value => value ? new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : '暂无成功记录'
const streak = row => row.current.cashDividend === null ? '当前年度缺失，待核验' : `${row.streakUnknown || row.streak === row.windowYears ? '至少 ' : ''}${row.streak} 年${row.streakUnknown ? '（更早年度缺失）' : row.streak === row.windowYears ? '（限观察窗口）' : ''}`
const missingRow = row => row.dividends.status !== 'ok' || row.financials.status !== 'ok' || row.current.cashDividend === null || row.current.parentProfit === null || row.current.operatingCashFlow === null || row.continuous === null
const rows = computed(() => {
  const term = query.value.trim().toLowerCase()
  const selected = (stats.value?.rows ?? []).filter(row => (!term || `${row.name} ${row.code}`.toLowerCase().includes(term)) && (industry.value === 'all' || (row.industry ?? 'unknown') === industry.value) &&
    (filter.value === 'all' || filter.value === 'decrease' && row.changeKind === 'decrease' || filter.value === 'profit' && row.current.profitCoverage !== null && row.current.profitCoverage < 1 || filter.value === 'cash' && row.current.cashCoverage !== null && row.current.cashCoverage < 1 || filter.value === 'missing' && missingRow(row) || filter.value === 'continuous' && row.continuous === true))
  const key = row => sort.value === 'growth' ? row.growth : sort.value === 'streak' ? row.streak : sort.value === 'profit' ? row.current.profitCoverage : row.current.cashDividend
  return selected.sort((a, b) => { const av = key(a), bv = key(b); return av === null ? bv === null ? a.code.localeCompare(b.code) : 1 : bv === null ? -1 : (sort.value === 'profit' ? av - bv : bv - av) || a.code.localeCompare(b.code) })
})
const selected = computed(() => stats.value?.rows.find(row => row.code === selectedCode.value))
function choose(member) { selectedCode.value = member.code; detail.value?.scrollIntoView?.({ behavior: 'smooth', block: 'start' }) }
function exportCsv() {
  if (!stats.value) return
  const safe = value => {
    const text = typeof value === 'number' ? String(value) : String(value ?? '').replace(/^[=+@\-\t\r]/, "'$&")
    return `"${text.replaceAll('"', '""')}"`
  }
  const lines = [['证券代码', '名称', '行业', '名单日期', '财年', '已实施分红(元)', '归母净利润(元)', '经营现金流(元)', '分红总额同比(%)', '变化状态', '利润覆盖(倍)', '非金融现金流覆盖(倍)', '已覆盖分红总额占比(%)', '连续分红年数下界', '连续性完整覆盖', '分红来源状态', '分红最近成功(UTC)', '财务来源状态', '财务最近成功(UTC)'],
    ...rows.value.map(row => [row.code, row.name, row.industry ?? '未分类', stats.value.membershipDate, year.value, row.current.cashDividend, row.current.parentProfit, row.current.operatingCashFlow, row.growth === null ? null : row.growth * 100, labels[row.changeKind], row.current.profitCoverage, row.current.cashCoverage, row.dividendShare === null ? null : row.dividendShare * 100, row.streak, row.continuous === null ? '未知' : row.continuous ? '连续' : '中断', row.dividends.status, row.dividends.lastSuccessAt, row.financials.status, row.financials.lastSuccessAt])]
  try { downloadBlob(new Blob(['\uFEFF' + lines.map(row => row.map(safe).join(',')).join('\r\n')], { type: 'text/csv;charset=utf-8' }), `H30269_分红基本面_${year.value}.csv`); message.value = '当前筛选结果 CSV 已生成，已请求浏览器下载。' } catch (error) { message.value = `导出失败：${error.message}` }
}
defineExpose({ loading, hasWarning })
for (const key of ['fundamentals', 'constituents']) dashboard.ensure(key)
</script>

<template>
  <section class="dividend-quality panel" aria-label="分红质量与基本面分析" :aria-busy="loading">
    <header class="quality-heading"><div><h2>分红质量与基本面分析</h2><p>H30269 成分股{{ instrument === '512890' ? ' · ETF 标的指数，非基金实际持仓' : '' }} · 年度已实施现金分红</p></div><button type="button" :disabled="loading" @click="dashboard.refresh(['fundamentals', 'constituents'])">{{ loading ? '读取中…' : '重新读取分红基本面' }}</button></header>
    <p class="quality-note">按分红所属财年与同年归母净利润、经营现金流对齐。展示截至采集时已实施的公司分红总额，包含来源统计的其他上市股类；不代表每股分红增长、指数权重贡献或 ETF 实际分红。</p>
    <p v-if="error" class="quality-warning" role="status">文件读取失败{{ inputs ? '，保留原分析和名单日期。' : '，暂无可用分析。' }}{{ error }}</p>
    <p v-else-if="loading" class="quality-note" role="status">正在读取分红基本面；已有分析暂显示原输入。</p>
    <p v-if="data" class="quality-note">基本面对应名单 {{ data.membershipDate ?? '暂无' }} · 观察年度 {{ data.years[0] }} — {{ data.years.at(-1) }} · 最近尝试 {{ time(data.lastAttemptAt) }}（北京时间） · {{ {ok:'个股来源本次采集成功',partial:'部分来源更新失败',stale:'沿用原名单和数据',unavailable:'数据不可用'}[data.status] }}{{ data.reason ? ` · ${data.reason}` : '' }}。</p>
    <p v-if="mismatch" class="quality-warning">基本面快照与当前名单不一致，下面仅分析快照内保存的名单，不将旧基本面套用到新成员。</p>
    <p v-if="inputs && !inputs.current" class="quality-warning">当前名单尚未读取，无法核验是否为最新名单；下方使用基本面快照内的原名单。</p>
    <p v-if="data?.membershipStatus === 'stale'" class="quality-warning">名单使用保留数据：{{ data.membershipReason }}</p>
    <p v-if="result.error" class="quality-warning" role="status">分析暂不可用：{{ result.error }}</p>
    <p v-if="!data && !loading" class="quality-note">尚无分红与基本面快照，缺失值不按零处理。</p>
    <template v-if="stats">
      <div class="quality-toolbar"><label>分析财年<select v-model.number="year" aria-label="分红分析财年"><option v-for="item in [...data.years].reverse()" :key="item" :value="item">{{ item }} 年</option></select></label><p class="quality-note">分红连续性观察 {{ stats.startYear }} — {{ year }}；年份为分红归属年度，实施可能发生在下一年。采集成功不保证每个年度和字段均有数据。</p></div>
      <div class="quality-metrics">
        <article><h3>已知分红金额覆盖</h3><strong>{{ stats.covered }} / {{ stats.total }}</strong><p>{{ stats.total - stats.covered }} 只缺失，不视为未分红</p></article>
        <article><h3>完整窗口连续分红</h3><strong>{{ stats.continuous }} / {{ stats.continuityKnown }}</strong><p>完整覆盖样本 · {{ stats.total - stats.continuityKnown }} 只连续性待核验</p></article>
        <article><h3>已覆盖公司分红总额</h3><strong>{{ amount(stats.totalDividend) }}</strong><p>人民币 · 未按指数权重加权</p></article>
        <article><h3>同样本分红总额同比</h3><strong>{{ riskPercent(stats.comparableGrowth, true) }}</strong><p>{{ stats.comparable }} 只两年可比，实施待完成者不纳入</p></article>
        <article><h3>归母利润足额覆盖</h3><strong>{{ stats.profitCovered }} / {{ stats.profitKnown }}</strong><p>覆盖倍数 ≥ 1 · 只统计正分红且利润已知</p></article>
        <article><h3>非金融经营现金流足额覆盖</h3><strong>{{ stats.cashCovered }} / {{ stats.cashKnown }}</strong><p>{{ stats.financialCount }} 只金融企业不参与通用现金流比较</p></article>
      </div>
      <div class="quality-changes" aria-label="分红增减分布"><span>总额增加 <b>{{ stats.changeCounts.increase }}</b></span><span>总额减少 <b>{{ stats.changeCounts.decrease }}</b></span><span>持平 <b>{{ stats.changeCounts.flat }}</b></span><span>由零转正 <b>{{ stats.changeCounts.resumed }}</b></span><span>连续零分红 <b>{{ stats.changeCounts.zero }}</b></span><span>实施待完成 <b>{{ stats.changeCounts.pending }}</b></span><span>不可比 <b>{{ stats.changeCounts.unknown }}</b></span></div>
      <p v-if="stats.staleSources" class="quality-warning">{{ stats.staleSources }} 个个股来源使用保留值或不可用；明细保留各来源的成功时间。合计与覆盖统计可能包含保留值。</p>
      <p class="quality-note">行业采用快照内保存的中证一级分类，按该份名单回看过去财年，不是历史指数成员回测。{{ unknownIndustries }} 只未分类单列{{ retainedIndustries ? `，${retainedIndustries} 只沿用保留分类` : '' }}。行业分类日期见个股详情。</p>
      <section class="quality-section" aria-label="行业分红总额贡献"><div class="quality-heading"><h3>行业分红总额贡献</h3><button type="button" @click="industry = 'all'">查看全部行业</button></div><p class="quality-note">占比 = 该行业已知公司分红总额 ÷ 全部已覆盖公司分红总额。未分类计入分母；缺金额不作零值，覆盖不足时仅代表已知样本。</p><ul class="quality-bars"><li v-for="group in stats.groups" :key="group.industry ?? 'unknown'"><button type="button" :aria-pressed="industry === (group.industry ?? 'unknown')" :aria-label="`筛选分红行业：${group.label}`" @click="industry = group.industry ?? 'unknown'"><span>{{ group.label }}<small>{{ group.covered }} / {{ group.count }} 只金额已知</small></span><strong>{{ amount(group.dividend) }} · {{ pct(group.share) }}</strong><span class="quality-track" aria-hidden="true"><span :style="{ width: `${(group.share ?? 0) * 100}%` }" /></span></button></li></ul></section>
      <section class="quality-section" aria-label="成分股分红与覆盖明细"><div class="quality-heading"><h3>个股分红与覆盖 · {{ rows.length }} / {{ stats.total }} 只</h3><button type="button" :disabled="!rows.length" @click="exportCsv">导出分红基本面 CSV</button></div><p v-if="message" class="quality-note" role="status">{{ message }}</p>
        <div class="quality-filters"><input v-model="query" type="search" aria-label="搜索分红分析股票代码或名称" placeholder="搜索代码 / 名称" /><label>行业<select v-model="industry" aria-label="分红分析行业"><option value="all">全部行业</option><option v-for="group in stats.groups" :key="group.industry ?? 'unknown'" :value="group.industry ?? 'unknown'">{{ group.label }}</option></select></label><label>筛选<select v-model="filter" aria-label="分红质量筛选"><option value="all">全部股票</option><option value="decrease">分红总额减少</option><option value="profit">归母利润不足覆盖</option><option value="cash">非金融现金流不足覆盖</option><option value="continuous">完整窗口连续分红</option><option value="missing">缺字段、年度或保留值</option></select></label><label>排序<select v-model="sort" aria-label="分红分析排序"><option value="dividend">分红总额从高到低</option><option value="growth">总额同比从高到低</option><option value="streak">连续分红年数从高到低</option><option value="profit">利润覆盖从低到高</option></select></label></div>
        <div class="quality-table" role="region" tabindex="0" aria-label="分红与覆盖明细，可横向滚动"><table><caption>{{ year }} 财年 · 公司分红金额及占已覆盖总额比例</caption><thead><tr><th scope="col">股票 / 行业</th><th scope="col">连续分红</th><th scope="col">已实施总额</th><th scope="col">总额同比</th><th scope="col">分红支付率</th><th scope="col">归母利润覆盖</th><th scope="col">非金融现金流覆盖</th><th scope="col">总额贡献</th><th scope="col">明细</th></tr></thead><tbody><tr v-for="row in rows" :key="row.code"><td><strong>{{ row.name }}</strong><small>{{ row.code }} · {{ row.industry ?? '未分类' }}{{ row.industryStatus === 'stale' ? '（保留分类）' : '' }}</small><small v-if="row.dividends.status !== 'ok' || row.financials.status !== 'ok'" class="quality-warning">分红 {{ row.dividends.status }} / 财务 {{ row.financials.status }}</small></td><td>{{ streak(row) }}<small>{{ row.knownYears }} / {{ row.windowYears }} 年金额已知</small></td><td>{{ amount(row.current.cashDividend) }}<small v-if="row.current.pending" class="quality-warning">实施尚未完成</small></td><td>{{ labels[row.changeKind] }}<small>{{ row.growth === null ? '—' : riskPercent(row.growth, true) }}</small></td><td>{{ pct(row.current.payoutRatio) }}<small v-if="row.current.coverageReason">{{ row.current.coverageReason }}</small></td><td :class="{ 'quality-warning': row.current.profitCoverage !== null && row.current.profitCoverage < 1 }">{{ times(row.current.profitCoverage) }}</td><td :class="{ 'quality-warning': row.current.cashCoverage !== null && row.current.cashCoverage < 1 }">{{ times(row.current.cashCoverage) }}<small v-if="row.current.cashReason">{{ row.current.cashReason }}</small></td><td>{{ pct(row.dividendShare) }}</td><td><button type="button" :aria-label="`查看${row.name}年度分红基本面`" @click="choose(row)">年度历史</button></td></tr></tbody></table><p v-if="!rows.length" class="quality-note">没有匹配的股票，请调整搜索或筛选。</p></div>
      </section>
      <section ref="detail" class="quality-section" aria-label="个股年度分红基本面详情"><h3>个股年度历史{{ selected ? ` · ${selected.name} ${selected.code}` : '' }}</h3><p v-if="!selected" class="quality-note">点击个股“年度历史”，查看分红、盈利与现金流原值及来源时间。</p><template v-else><p class="quality-note">{{ selected.industry ?? '未分类' }} · 分类日期 {{ selected.industryDate ?? '暂无' }} · 分红最近成功 {{ time(selected.dividends.lastSuccessAt) }}，最近尝试 {{ time(selected.dividends.lastAttemptAt) }} · 财务最近成功 {{ time(selected.financials.lastSuccessAt) }}，最近尝试 {{ time(selected.financials.lastAttemptAt) }}（北京时间）。</p><p v-if="selected.dividends.reason || selected.financials.reason" class="quality-warning">{{ selected.dividends.reason }} {{ selected.financials.reason }}</p><div class="quality-years" aria-label="分红连续性年度记录"><span v-for="item in selected.history" :key="item.year" :class="{ missing: item.cashDividend === null, zero: item.cashDividend === 0 }">{{ item.year }} · {{ item.cashDividend === null ? '缺失' : item.cashDividend > 0 ? '已分红' : '明确零值' }}</span></div><div class="quality-table"><table><caption>归属财年与同年年报 · 金额为人民币亿元</caption><thead><tr><th>财年</th><th>已实施分红</th><th>计划分红</th><th>归母净利润</th><th>经营现金流</th><th>ROE</th><th>年报公告 / 修订日期</th></tr></thead><tbody><tr v-for="item in [...selected.history].reverse()" :key="item.year"><td>{{ item.year }}<small v-if="item.pending" class="quality-warning">实施待完成</small></td><td>{{ amount(item.cashDividend) }}</td><td>{{ amount(item.plannedDividend) }}</td><td>{{ amount(item.parentProfit) }}</td><td>{{ amount(item.operatingCashFlow) }}</td><td>{{ item.roe === null ? '—' : `${item.roe.toFixed(2)}%` }}</td><td>{{ item.noticeDate ?? '—' }}<small>{{ item.updatedDate ?? '—' }}</small></td></tr></tbody></table></div><p class="quality-note">计划金额仅作实施进度参考，不计入已实施分红。缺失年度不能确认未分红；当前连续年数限观察窗口，不代表上市以来。</p><p class="quality-links"><a :href="`https://data.eastmoney.com/yjfp/detail/${selected.code}.html`" target="_blank" rel="noopener noreferrer">查看分红来源</a><a :href="`https://emweb.securities.eastmoney.com/PC_HSF10/FinanceAnalysis/Index?type=web&amp;code=${selected.exchange === 'SSE' ? 'SH' : 'SZ'}${selected.code}`" target="_blank" rel="noopener noreferrer">查看财务来源</a></p></template></section>
    </template>
    <details class="quality-method quality-note"><summary>分红质量的计算口径与来源</summary><p>公司年度已实施分红金额来自东方财富分红融资年度统计，归母利润、经营现金流和加权 ROE 来自同财年年报主要指标，金额统一为人民币元。不同币种、身份或年度异常时拒绝记录；原币种不能直接混算。可包含公司其他上市股类的现金分红，不折算成该 A 股每股金额。</p><p>支付率 = 已实施分红 ÷ 同年归母净利润；利润覆盖 = 同年归母净利润 ÷ 已实施分红；非金融现金流覆盖 = 同年经营现金流 ÷ 已实施分红。正分红且分子已知时计算覆盖，负利润或负现金流保留负覆盖值；归母净利润非正时不显示支付率。零分红不生成无限覆盖倍数。覆盖 ≥ 1 只表示该口径的年度金额足额，不是未来分红保证。</p><p>经营现金流没有扣除资本开支，不是自由现金流，也不等同于可分配现金。来源标记为银行、保险、证券、金融、信托或中证行业为金融的企业，展示原现金流，排除通用现金流覆盖比较。合并经营现金流与归母净利润也有报表范围差异，应结合企业年报理解。</p><p>连续分红从所选财年向前逐年检查正的已实施分红金额；遇明确零值停止，遇缺失停止并标为下界。完整窗口连续性只有所有年度金额已知才判定。总额同比使用相邻财年，不用最近有值的旧年份替代；前期零值不生成增长百分比，标为由零转正或连续零值。计划金额大于已实施金额时标实施待完成，排除完成状态的增减分布及同样本同比汇总。</p><p>行业和个股贡献以已覆盖公司分红总额为分母，金融企业和未分类均计入；不能解读为指数股息率、指数收益贡献、ETF 收益或持仓权重。用当前快照名单回看过去财年具有成员选择偏差，历史成员变化见独立的成分结构模块。</p><p>数据由独立分红基本面采集更新；重新读取只读取站点静态快照。每只股票的分红与财务来源单独保留成功时间，失败不抹除原值；采集成功仍可能缺字段。数据披露存在时滞，修订可覆盖原年度值，不构造历史时点回测。</p><p><a href="https://data.eastmoney.com/yjfp/" target="_blank" rel="noopener noreferrer">东方财富分红送配</a> · <a href="https://data.eastmoney.com/bbsj/" target="_blank" rel="noopener noreferrer">东方财富财务数据</a></p></details>
  </section>
